import { PrismCard } from './components/PrismCard';
import { PromotionsSection } from './components/PromotionsSection';
import { ThreeDShowcaseWrapper } from './components/ThreeDShowcaseWrapper';

export default function HomePage() {
  return (
    <main className="min-h-screen">
      {/* Hero Section with 3D Showcase */}
      <section className="relative min-h-screen flex flex-col items-center justify-center bg-gradient-to-br from-gray-50 via-white to-gray-100 py-20">
        <div className="container mx-auto px-4 text-center mb-12">
          <h1 className="text-6xl md:text-8xl font-bold text-gray-900 mb-6">
            MERTMAX <span className="text-red-600">ЕООД</span>
          </h1>
          <p className="text-2xl md:text-3xl text-gray-700 max-w-4xl mx-auto mb-8">
            Три бизнеса под едно име - Супермаркет, Индустриална база, Строителен магазин
          </p>
          <p className="text-xl text-gray-600 max-w-2xl mx-auto">
            Обслужваме клиенти в Самуил, Разград и региона
          </p>
        </div>
        
        {/* 3D Logo Showcase */}
        <div className="container mx-auto px-4 max-w-4xl">
          <ThreeDShowcaseWrapper />
        </div>
      </section>

      {/* Divisions Section with Prism Cards */}
      <section className="py-24 bg-white">
        <div className="container mx-auto px-4">
          <h2 className="text-4xl md:text-5xl font-bold text-center mb-16">
            Нашите <span className="text-red-600">бизнеси</span>
          </h2>
          <div className="grid md:grid-cols-3 gap-8 max-w-7xl mx-auto">
            <PrismCard
              title="Супермаркет САМУИЛ"
              description="Хранителни стоки, напитки, дом и градина, козметика и деликатеси в центъра на Самуил"
              href="/supermarket"
              iconName="ShoppingCart"
              accent="grocery"
              label="Разгледай асортимента"
            />
            <PrismCard
              title="Индустриална база"
              description="Строителни материали, метални изделия и едроплощадна търговия за промишлеността"
              href="/industrial"
              iconName="Building2"
              accent="industrial"
              label="Виж услугите"
            />
            <PrismCard
              title="Строителен магазин"
              description="Инструменти, материали, ВиК и електро за всеки строителен проект"
              href="/construction"
              iconName="HardHat"
              accent="construction"
              label="Открий продуктите"
            />
          </div>
        </div>
      </section>

      {/* Promotions Section */}
      <PromotionsSection />

      {/* CTA Section */}
      <section className="py-24 bg-gradient-to-br from-red-600 to-pink-600 text-white">
        <div className="container mx-auto px-4 text-center">
          <h2 className="text-4xl md:text-5xl font-bold mb-6">
            Готови сме да ви обслужим
          </h2>
          <p className="text-xl mb-8 max-w-2xl mx-auto">
            Посетете ни в един от нашите обекти или се свържете с нас за повече информация
          </p>
          <a 
            href="/contact" 
            className="inline-block bg-white text-red-600 px-8 py-4 rounded-lg font-semibold text-lg hover:bg-gray-100 transition-colors"
          >
            Свържете се с нас
          </a>
        </div>
      </section>
    </main>
  );
}
